<script setup lang="ts">
import AppLayout from '@/layouts/AppLayout.vue';import{Head,router,useForm}from'@inertiajs/vue3';const props=defineProps<{exam:any;attempts:any[]}>();const grade=(answer:any)=>{const score=prompt('Nilai esai',String(answer.score??0));if(score!==null)router.post(`/ujian/jawaban/${answer.id}/nilai`,{score:Number(score)},{preserveScroll:true})};
</script>
<template><Head title="Hasil Ujian"/><AppLayout><main class="view space-y-6"><section class="hero-card result-hero"><div><p class="eyebrow">Hasil CBT</p><h1>{{ exam.title }}</h1><p>Koreksi esai, tinjau pelanggaran, lalu terbitkan hasil dan sinkronkan nilai.</p></div><div class="actions"><a class="secondary-button" :href="`/ujian/${exam.id}/hasil/export`">Export CSV</a><button class="primary-button" @click="router.post(`/ujian/${exam.id}/hasil/terbitkan`)">Terbitkan hasil</button></div></section><section class="panel result-list"><article v-for="a in attempts" :key="a.id"><header><div><strong>{{ a.student?.name }}</strong><small>{{ a.student?.nis }} · {{ a.status }}</small></div><div><b>{{ a.score??'—' }}</b><small>{{ a.violation_count }} pelanggaran</small></div></header><div v-for="ans in a.answers.filter((x:any)=>(x.question_version??x.question)?.type==='essay')" :key="ans.id" class="essay"><p>{{ (ans.question_version??ans.question)?.prompt }}</p><blockquote>{{ ans.answer||'(kosong)' }}</blockquote><button @click="grade(ans)">{{ ans.score===null?'Nilai esai':`Nilai: ${ans.score}` }}</button></div></article><p v-if="!attempts.length" class="empty-state">Belum ada attempt.</p></section></main></AppLayout></template>
<style scoped>.result-hero,.actions,.result-list article header{display:flex;justify-content:space-between;align-items:center;gap:.7rem}.result-list{display:grid;gap:.8rem;padding:1rem}.result-list article{padding:1rem;border:1px solid #e2e8f0;border-radius:.8rem}.result-list small{display:block;color:#64748b}.result-list b{font-size:1.4rem}.essay{margin-top:.7rem;padding:.8rem;background:#f8fafc;border-radius:.6rem}.essay blockquote{margin:.4rem 0;color:#475569}.essay button{color:#4f46e5;font-weight:800}@media(max-width:760px){.result-hero{align-items:stretch;flex-direction:column}}</style>
